    /**
     * Tests getting all InventorySources.
     *
     * @return    Collection
     */
    public List<InventorySource> testGetAll() throws Throwable {
    LOGGER.info( "InventorySourceTest:testGetAll() - Retrieving Collection of InventorySources:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all InventorySource : " );
    List<InventorySource> collection  = null;

    try {
        // call the static get method on the InventorySourceService
        collection = service.getAllInventorySource();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            InventorySource currEntity  = null;
            Iterator<InventorySource> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getInventorySourceId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

